set -e
d=$(mktemp -d)
cat > "$d/regress.py" <<'ASH_REGRESS'
"""Behaviour regression for taskman: every command through CLI, web handler and batch runner.

usage: regress.py GOLDEN.json [--record]
"""
import io
import json
import os
import shlex
import subprocess
import sys
import tempfile

sys.path.insert(0, os.getcwd())
os.environ["TASKMAN_TODAY"] = "2026-03-10"
os.environ.pop("TASKMAN_DB", None)

from taskman.batch import run_batch  # noqa: E402
from taskman.cli import main  # noqa: E402
from taskman.store import Store  # noqa: E402
from taskman.web import handle  # noqa: E402

STEPS = [
    ["help"], ["?"], ["list"], ["stats"], ["export"], ["export", "--format", "json"], ["purge"], ["search", "x"],
    ["add"], ["add", "-p", "high"], ["add", "   "],
    ["add", "Write", "report", "-p", "high", "-t", "work,Q1", "-d", "2026-03-12"],
    ["new", "Buy milk", "-t", "home", "-d", "today"],
    ["add", "Call", "mom", "-p", "u", "-d", "tomorrow"],
    ["add", "Fix bike", "-p", "low", "-t", "home, bike,home", "-d", "2026-03-01"],
    ["add", "Plan trip", "-d", "+14d", "-t", "#travel"],
    ["add", "Old", "thing", "-d", "2026-02-30"], ["add", "x", "-d", "03/04/2026"], ["add", "x", "-p", "extreme"],
    ["add", "x", "-t", "bad tag!"], ["add", "x", "-t", ","], ["add", "x", "-p"], ["add", "x", "--bogus"],
    ["add", "Temperature", "-5", "outside", "-p", "NORMAL"],
    ["add", 'Quote "this", ok', "-t", "a-b,c1"],
    ["list"], ["ls", "--all"], ["list", "--sort", "pri"], ["list", "--sort", "due"], ["list", "--sort", "name"],
    ["list", "--tag", "home"], ["list", "--tag", "HOME"], ["list", "extra"], ["list", "-a", "--tag", "nope"],
    ["list", "--tag"], ["list", "--tag", "bad tag"],
    ["show", "1"], ["show", "#2"], ["show", "4"], ["show"], ["show", "99"], ["show", "abc"], ["show", "0"], ["show", "1", "2"],
    ["done", "2", "3"], ["done"], ["done", "2"], ["done", "4", "99", "5"], ["done", "x", "5"], ["done", "#5"],
    ["undo", "2"], ["reopen", "5"], ["undo", "1"], ["undo"], ["undo", "1", "2"],
    ["rename", "1", "Write", "final", "report"], ["rename", "1"], ["rename", "42", "x"], ["rename", "1", " "],
    ["tag", "1", "urgent,work"], ["tag", "1"], ["tag", "1", "bad tag"], ["untag", "1", "q1,nothere"],
    ["untag", "5", "travel"], ["untag", "99", "x"], ["tag", "nope", "x"],
    ["pri", "1", "low"], ["priority", "1", "N"], ["pri", "1", "meh"], ["pri", "1"], ["pri", "77", "high"],
    ["due", "1", "none"], ["due", "1", "2026-03-09"], ["due", "3", "2026-04-01"], ["due", "3", "NONE"],
    ["due", "1", "next week"], ["due", "1"], ["due", "6", "+0d"], ["due", "7", "+1000d"],
    ["search", "home"], ["find", "#home"], ["search", "BIKE"], ["search"], ["search", "zzz"], ["search", "#bik"],
    ["search", "write", "final"], ["search", '"this"'],
    ["stats"], ["stats", "now"],
    ["export"], ["export", "--format", "json"], ["export", "-f", "xml"], ["export", "extra"], ["export", "--format"],
    ["list", "--all", "--sort", "due"],
    ["purge", "--dry-run"], ["purge", "-n"], ["purge", "now"], ["purge", "--force"], ["purge"], ["purge"],
    ["rm", "6"], ["del", "6"], ["remove", "1"], ["rm"], ["rm", "1", "2"],
    ["list", "--all"], ["show", "7"], ["stats"], ["export", "--format", "json"],
    ["frobnicate"], ["LIST"], ["Help"], ["snooze-not"],
]


def run_cli(tmp):
    db = os.path.join(tmp, "cli.json")
    rows = []
    for step in STEPS:
        out, err = io.StringIO(), io.StringIO()
        code = main(["--db", db, *step], stdout=out, stderr=err)
        rows.append([step, code, out.getvalue(), err.getvalue()])
    for argv in ([], ["--db"], ["--db", db]):
        out, err = io.StringIO(), io.StringIO()
        rows.append([[a if a != db else "<db>" for a in argv], main(argv, stdout=out, stderr=err), out.getvalue(), err.getvalue()])
    env_db = os.path.join(tmp, "env.json")
    os.environ["TASKMAN_DB"] = env_db
    try:
        for step in (["add", "via", "env"], ["list"]):
            out, err = io.StringIO(), io.StringIO()
            rows.append(["env", step, main(step, stdout=out, stderr=err), out.getvalue(), err.getvalue()])
    finally:
        del os.environ["TASKMAN_DB"]
    with open(db, encoding="utf-8") as f:
        rows.append(["db", json.load(f)])
    for step in (["list", "--all"], ["show", "2"], ["bogus"], ["done", "2"]):
        p = subprocess.run([sys.executable, "-m", "taskman", "--db", db, *step], capture_output=True, text=True,
                           cwd=os.getcwd(), env=dict(os.environ))
        rows.append(["proc", step, p.returncode, p.stdout, p.stderr])
    return rows


def run_web():
    store = Store()
    rows = []
    for step in STEPS:
        rows.append([step, handle({"method": "POST", "path": "/commands/" + step[0], "body": {"args": step[1:]}}, store)])
    extra = [
        {"method": "GET", "path": "/commands"},
        {"method": "get", "path": "/commands", "body": None},
        {"method": "POST", "path": "/commands"},
        {"method": "GET", "path": "/commands/list"},
        {"method": "DELETE", "path": "/commands/rm", "body": {"args": ["2"]}},
        {"method": "GET", "path": "/nope"},
        {"method": "POST", "path": "/commands/"},
        {"path": "/"},
        {"method": "POST", "path": "/commands/list"},
        {"method": "POST", "path": "/commands/list", "body": None},
        {"method": "POST", "path": "/commands/list", "body": {}},
        {"method": "POST", "path": "/commands/list", "body": {"args": "--all"}},
        {"method": "POST", "path": "/commands/list", "body": {"args": [1]}},
        {"method": "POST", "path": "/commands/list", "body": ["--all"]},
        {"method": "POST", "path": "/commands/nope", "body": {"args": [3]}},
        {"method": "POST", "path": "/commands/nope", "body": {"args": []}},
        {"method": "POST", "path": "/commands/ls", "body": {"args": ["--all"], "extra": True}},
        {"method": "POST", "path": "/commands/?", "body": {"args": []}},
    ]
    for req in extra:
        rows.append([req, handle(req, store)])
    rows.append(["state", [t.to_dict() for t in store.all()]])
    return rows


def run_batches():
    lines = [shlex.join(step) for step in STEPS]
    rows = [["continue", run_batch(Store(), lines, continue_on_error=True)]]
    rows.append(["stop", run_batch(Store(), lines)])
    script = ["# setup", "", "add 'a b' -t x", "   ", "  add c  ", "add 'unclosed", "list --all", "#done 1", "done 1 2",
              "ls", "show 1 2"]
    rows.append(["script-continue", run_batch(Store(), script, continue_on_error=True)])
    rows.append(["script-stop", run_batch(Store(), script)])
    rows.append(["empty", run_batch(Store(), [])])
    rows.append(["blank-word", run_batch(Store(), ["''", "help"], continue_on_error=True)])
    return rows


def collect():
    with tempfile.TemporaryDirectory() as tmp:
        return {"cli": run_cli(tmp), "web": run_web(), "batch": run_batches()}


def diff(got, want, path="", out=None):
    out = [] if out is None else out
    if isinstance(want, dict) and isinstance(got, dict):
        for k in sorted(set(want) | set(got)):
            diff(got.get(k), want.get(k), f"{path}.{k}", out)
    elif isinstance(want, list) and isinstance(got, list) and len(want) == len(got):
        for i, (g, w) in enumerate(zip(got, want)):
            diff(g, w, f"{path}[{i}]", out)
    elif got != want:
        out.append(f"{path}: got {got!r}\n    want {want!r}")
    return out


if __name__ == "__main__":
    got = json.loads(json.dumps(collect()))
    if "--record" in sys.argv:
        with open(sys.argv[1], "w") as f:
            json.dump(got, f, indent=1)
        sys.exit(0)
    with open(sys.argv[1]) as f:
        want = json.load(f)
    problems = []
    for part in ("cli", "web", "batch"):
        g, w = got[part], want[part]
        for i, row in enumerate(w):
            if i >= len(g):
                problems.append(f"{part}: missing row {i}")
                break
            label = json.dumps(row[0]) if not isinstance(row[0], str) else row[0] + " " + json.dumps(row[1])[:80]
            for p in diff(g[i], row):
                problems.append(f"{part} {label}: {p}")
    if problems:
        print(f"{len(problems)} behaviour differences, first ones:", file=sys.stderr)
        print("\n".join(problems[:12]), file=sys.stderr)
        sys.exit(1)
    print("regression ok")
ASH_REGRESS
cat > "$d/golden.json" <<'ASH_GOLDEN'
