cat > "$d/api_test.py" <<'ASH_API'
import io
import os
import sys
import tempfile

sys.path.insert(0, os.getcwd())
os.environ["TASKMAN_TODAY"] = "2026-03-10"
os.environ.pop("TASKMAN_DB", None)

import taskman  # noqa: E402,F401
from taskman.batch import run_batch  # noqa: E402
from taskman.cli import main  # noqa: E402
from taskman.errors import ConflictError, UsageError  # noqa: E402
from taskman.registry import Command, CommandConflictError, Registry, UnknownCommandError, registry  # noqa: E402
from taskman.store import Store  # noqa: E402
from taskman.web import handle  # noqa: E402


def eq(got, want, what):
    assert got == want, f"{what}:\n  got  {got!r}\n  want {want!r}"


def raises(exc, fn, what):
    try:
        fn()
    except exc:
        return
    except Exception as e:  # noqa
        raise AssertionError(f"{what}: raised {e!r}, want {exc.__name__}")
    raise AssertionError(f"{what}: did not raise {exc.__name__}")


# ---- Registry API on a fresh registry ----
assert issubclass(CommandConflictError, ValueError) and issubclass(UnknownCommandError, LookupError)
r = Registry()


def f(store, args):
    return "f"


eq(r.command("alpha", usage="alpha", summary="A", aliases=("a1", "a2"))(f) is f, True, "decorator returns the function")
cb = r.register("beta", f, usage="beta X", summary="B", order=50)
assert isinstance(cb, Command), "register returns the Command"
r.register("gamma", f, usage="gamma", summary="G")
r.register("delta", f, usage="delta", summary="D", order=50, aliases=["dd"])
eq([c.name for c in r.commands()], ["beta", "delta", "alpha", "gamma"], "order, then registration sequence")
c = r.resolve("a2")
eq((c.name, c.func is f, c.usage, c.summary, c.aliases, c.order), ("alpha", True, "alpha", "A", ("a1", "a2"), 100), "Command fields")
eq(r.resolve("dd").aliases, ("dd",), "aliases stored as a tuple")
eq(r.resolve("beta"), cb, "resolve by name")
eq(("a1" in r, "beta" in r, "zeta" not in r), (True, True, True), "__contains__")
raises(UnknownCommandError, lambda: r.resolve("zeta"), "resolve unknown")
for name, aliases in [("alpha", ()), ("x", ("beta",)), ("a1", ()), ("y", ("q", "a2")), ("z", ("z",)), ("w", ("q", "q"))]:
    raises(CommandConflictError, lambda: r.register(name, f, usage=name, summary="s", aliases=aliases), f"conflict {name} {aliases}")
    raises(CommandConflictError, lambda: r.command(name, usage=name, summary="s", aliases=aliases)(f), f"decorator conflict {name}")
eq([w in r for w in ("x", "y", "z", "w", "q")], [False] * 5, "failed registrations leave no trace")
eq([c.name for c in r.commands()], ["beta", "delta", "alpha", "gamma"], "registry unchanged after conflicts")
r.register("eps", f, usage="eps", summary="E", aliases=("e",))
raises(UnknownCommandError, lambda: r.unregister("e"), "unregister takes the canonical name")
raises(UnknownCommandError, lambda: r.unregister("nope"), "unregister unknown")
r.unregister("alpha")
eq(("alpha" in r, "a1" in r, "a2" in r, "eps" in r), (False, False, False, True), "unregister removes aliases")
r.register("a1", f, usage="a1", summary="again")
eq([c.name for c in r.commands()], ["beta", "delta", "gamma", "eps", "a1"], "names are reusable after unregister")
eq(Registry().commands(), [], "registries are independent")

# ---- the app registry ----
BUILTIN = ["add", "list", "show", "done", "undo", "rm", "rename", "tag", "untag", "pri", "due", "snooze", "search",
           "stats", "purge", "export", "help"]
eq([c.name for c in registry.commands()], BUILTIN, "built-in commands in help order")
assert all(0 <= c.order <= 999 for c in registry.commands()), "built-in orders must be within 0..999"
eq(registry.resolve("later").name, "snooze", "snooze alias")
eq(registry.resolve("?").name, "help", "help alias")

tmp = tempfile.mkdtemp()
db = os.path.join(tmp, "t.json")


def cli(*argv):
    out, err = io.StringIO(), io.StringIO()
    code = main(["--db", db, *argv], stdout=out, stderr=err)
    return code, out.getvalue(), err.getvalue()


def web(name, *args):
    return handle({"method": "POST", "path": "/commands/" + name, "body": {"args": list(args)}}, Store(db))


# ---- a command registered at runtime works through all three entry points ----
seen = []


def echo(store, args):
    seen.append(store)
    if args[:1] == ["boom"]:
        raise ConflictError("boom!")
    if args[:1] == ["bad"]:
        raise UsageError("usage: zecho [WORDS...]")
    return "echo:" + "|".join(args)


registry.register("zecho", echo, usage="zecho [WORDS...]", summary="echo words", aliases=("ze",), order=5000)
eq(cli("ze", "a", "b c"), (0, "echo:a|b c\n", ""), "cli runtime command")
eq(cli("zecho", "boom"), (1, "", "error: boom!\n"), "cli runtime conflict")
eq(cli("zecho", "bad"), (2, "", "error: usage: zecho [WORDS...]\n"), "cli runtime usage")
assert all(isinstance(s, Store) for s in seen), "commands receive a Store"
help_lines = cli("help")[1].splitlines()
eq(help_lines[-1], "  zecho [WORDS...]                    echo words (aliases: ze)", "help lists runtime command last")
eq(len(help_lines), 19, "help line count with runtime command")
eq(web("ze", "x"), {"status": 200, "body": {"output": "echo:x", "lines": ["echo:x"]}}, "web runtime command")
eq(web("zecho", "boom"), {"status": 409, "body": {"error": "boom!", "kind": "conflict"}}, "web runtime conflict")
listing = handle({"method": "GET", "path": "/commands"}, Store())["body"]["commands"]
eq(listing[-1], {"name": "zecho", "aliases": ["ze"], "usage": "zecho [WORDS...]", "summary": "echo words"}, "GET /commands")
eq(run_batch(Store(), ["ze 'a b'", "zecho boom", "zecho"], continue_on_error=True),
   ["> ze 'a b'", "echo:a b", "> zecho boom", "! conflict: boom!", "> zecho", "echo:", "= 2 ok, 1 failed"], "batch runtime command")
registry.unregister("zecho")
eq(cli("ze"), (2, "", "error: unknown command: ze (try 'help')\n"), "cli after unregister")
eq(web("zecho")["status"], 404, "web after unregister")
eq(run_batch(Store(), ["ze"]), ["> ze", "! unknown: unknown command: ze", "= 0 ok, 1 failed"], "batch after unregister")

# ---- replacing a built-in changes every entry point ----
orig = registry.resolve("stats")
registry.unregister("stats")
registry.register("stats", lambda store, args: "patched", usage=orig.usage, summary=orig.summary, aliases=orig.aliases,
                  order=orig.order)
eq(cli("stats"), (0, "patched\n", ""), "cli dispatches built-ins through the registry")
eq(web("stats")["body"].get("output"), "patched", "web dispatches built-ins through the registry")
eq(run_batch(Store(), ["stats"]), ["> stats", "patched", "= 1 ok, 0 failed"], "batch dispatches built-ins through the registry")
orig_rm = registry.resolve("rm")
registry.unregister("rm")
eq(cli("del", "1")[0], 2, "removing a built-in removes its aliases from the cli")
registry.register("rm", orig_rm.func, usage=orig_rm.usage, summary=orig_rm.summary, aliases=orig_rm.aliases, order=orig_rm.order)
registry.unregister("stats")
registry.register("stats", orig.func, usage=orig.usage, summary=orig.summary, aliases=orig.aliases, order=orig.order)

